import type { OperationContext } from "@btst/stack/plugins/api";

/** Stable public source metadata; providers are registered only by application code. */
export type SearchSource = {
	id: string;
	label: string;
};

/** A provider's already-authorized public projection. Snippets are plain text. */
export type SearchProviderResult = {
	resourceId: string;
	title: string;
	snippet: string;
	href: string;
};

/** Providers must apply visibility before returning records or continuation metadata. */
export interface SearchProvider extends SearchSource {
	search(context: {
		q: string;
		limit: number;
		request: Request;
		identity: OperationContext<unknown, unknown>["identity"];
	}): Promise<{ items: readonly SearchProviderResult[]; hasMore: boolean }>;
}

/** Result identity is scoped to its source, with no comparable relevance score. */
export type SearchResult = SearchProviderResult & {
	key: string;
	sourceId: string;
	sourceLabel: string;
};

export interface SearchInput {
	q: string;
	sources?: readonly string[] | string;
	page?: number;
	limit?: number;
}

/** Pagination covers a bounded result window, never an exact global total. */
export type SearchResponse = {
	items: SearchResult[];
	sources: SearchSource[];
	page: number;
	limit: number;
	hasMore: boolean;
	nextPage: number | null;
	truncated: boolean;
};

export interface SearchBackendConfig {
	providers?: readonly SearchProvider[];
}

import { z } from "zod";

export const SEARCH_MAX_SOURCES = 8;
export const SEARCH_MAX_RESULTS = 200;
export const SEARCH_MAX_PAGES = 10;
export const searchSourceIdSchema = z.string().regex(/^[a-z][a-z0-9-]{0,63}$/);
export const searchInputSchema = z.object({
	q: z.string().trim().max(200),
	sources: z.preprocess(
		(value) =>
			typeof value === "string" ? value.split(",").filter(Boolean) : value,
		z.array(searchSourceIdSchema).max(SEARCH_MAX_SOURCES).optional(),
	),
	page: z.coerce.number().int().min(1).max(SEARCH_MAX_PAGES).default(1),
	limit: z.coerce.number().int().min(1).max(20).default(20),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

export const searchPermissions = definePermissions("search", {
	query: {
		read: permission(z.object({ sources: z.array(z.string()) })),
	},
});

"use client";

import { useEffect, useId, useState } from "react";
import { usePluginOverrides } from "@btst/stack/context";
import { Input } from "@/components/ui/input";
import { SEARCH_PLUGIN_ID } from "../../constants";
import type { SearchPluginOverrides } from "../../overrides";
import type { SearchListState } from "../../search-state";
import {
	SearchPagination,
	SearchResults,
	SearchStatus,
} from "../search-results";
import { SourceFilter } from "../source-filter";
import { useSearchState } from "@btst/plugin-search/client/hooks";

export function SearchPage({
	initialSearch,
}: {
	initialSearch?: SearchListState;
}) {
	const id = useId();
	const [hydrated, setHydrated] = useState(false);
	useEffect(() => setHydrated(true), []);
	const overrides = usePluginOverrides<SearchPluginOverrides>(SEARCH_PLUGIN_ID);
	const { state, setState, result, loading } = useSearchState({
		initialSearch,
	});
	return (
		<main
			className="container mx-auto min-w-0 max-w-4xl space-y-6 px-4 py-8"
			data-testid="search-page"
		>
			<h1 className="text-3xl font-semibold tracking-tight">
				{overrides.title ?? "Search"}
			</h1>
			<fieldset
				disabled={!hydrated}
				aria-label="Search controls"
				className="min-w-0 space-y-6"
			>
				<div className="space-y-2">
					<label htmlFor={id} className="text-sm font-medium">
						Search
					</label>
					<Input
						id={id}
						type="search"
						data-testid="search-input"
						maxLength={200}
						placeholder={overrides.placeholder ?? "Search content…"}
						value={state.q}
						onChange={(event) =>
							setState({ q: event.target.value, page: 1 }, { replace: true })
						}
					/>
				</div>
				{result.data && (
					<SourceFilter
						sources={result.data.sources}
						value={state.sources}
						onChange={(sources) => setState({ sources, page: 1 })}
					/>
				)}
				<section
					className="rounded-md border"
					aria-label="Search results"
					aria-busy={loading}
				>
					<div aria-live="polite">
						<SearchStatus
							query={state.q}
							data={result.data}
							loading={loading}
							error={result.error}
							emptyMessage={overrides.emptyMessage}
							onRetry={() => void result.refetch()}
						/>
					</div>
					{!result.error && !loading && result.data && (
						<SearchResults data={result.data} />
					)}
					{!result.error && state.q.trim() && result.data && (
						<SearchPagination
							page={state.page}
							hasMore={result.data.hasMore}
							loading={loading}
							onPageChange={(page) => setState({ page })}
						/>
					)}
				</section>
				{result.data?.truncated && (
					<p className="text-sm text-muted-foreground">
						Showing a limited result window. Refine your query to find more
						content.
					</p>
				)}
			</fieldset>
		</main>
	);
}

"use client";

import { lazy } from "react";
import {
	ComposedRoute,
	type FallbackProps,
} from "@btst/stack/client/components";
import { Button } from "@/components/ui/button";
import type { SearchListState } from "../../search-state";

const Page = lazy(() =>
	import("./search-page.internal").then((module) => ({
		default: module.SearchPage,
	})),
);

function SearchLoading() {
	return (
		<p className="p-8" role="status">
			Loading search…
		</p>
	);
}

function SearchError({ resetErrorBoundary }: FallbackProps) {
	return (
		<div className="space-y-4 p-8" role="alert">
			<p>Search is unavailable.</p>
			<Button type="button" variant="outline" onClick={resetErrorBoundary}>
				Retry loading
			</Button>
		</div>
	);
}

export function SearchPageComponent({
	initialSearch,
}: {
	initialSearch?: SearchListState;
}) {
	return (
		<ComposedRoute
			path="/search"
			PageComponent={Page}
			LoadingComponent={SearchLoading}
			ErrorComponent={SearchError}
			props={{ initialSearch }}
			onError={(error) => console.error("[btst/search]", error)}
		/>
	);
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useStack } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import {
	Command,
	CommandInput,
	CommandItem,
	CommandList,
} from "@/components/ui/command";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
} from "@/components/ui/dialog";
import { SearchPagination, SearchStatus } from "./search-results";
import { SourceFilter } from "./source-filter";
import { useSearchState } from "@btst/plugin-search/client/hooks";

/** Shared discovery options. Supplying sources fixes the allowed UI scope. */
export interface SearchPresentationProps {
	/** Fixed provider IDs; URL source filters cannot expand this selection. */
	sources?: readonly string[];
	className?: string;
	placeholder?: string;
	emptyMessage?: string;
	title?: string;
}

/** Controlled discovery dialog with keyboard selection and router navigation. */
export interface SearchDialogProps extends SearchPresentationProps {
	open: boolean;
	onOpenChange: (open: boolean) => void;
}

export function SearchDialog({
	open,
	onOpenChange,
	sources,
	className,
	placeholder = "Search content…",
	emptyMessage,
	title = "Search",
}: SearchDialogProps) {
	const { router } = useStack();
	const { state, setState, result, fixedSources, loading } = useSearchState({
		sources,
		enabled: open,
	});
	const navigate = async (href: string) => {
		if (router?.navigate) await router.navigate(href);
		else window.location.assign(href);
		onOpenChange(false);
	};
	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			<DialogContent className={className} data-testid="search-modal">
				<DialogHeader>
					<DialogTitle>{title}</DialogTitle>
					<DialogDescription>
						Find content across the available sources.
					</DialogDescription>
				</DialogHeader>
				<Command shouldFilter={false}>
					<CommandInput
						aria-label="Search"
						data-testid="search-input"
						placeholder={placeholder}
						value={state.q}
						maxLength={200}
						onValueChange={(q) => setState({ q, page: 1 }, { replace: true })}
					/>
					{!fixedSources && result.data && (
						<div className="p-3">
							<SourceFilter
								sources={result.data.sources}
								value={state.sources}
								onChange={(value) => setState({ sources: value, page: 1 })}
							/>
						</div>
					)}
					<CommandList aria-busy={loading} className="max-h-[400px]">
						<SearchStatus
							query={state.q}
							data={result.data}
							loading={loading}
							error={result.error}
							emptyMessage={emptyMessage}
							onRetry={() => void result.refetch()}
						/>
						{!result.error &&
							!loading &&
							result.data?.items.map((item) => (
								<CommandItem
									key={item.key}
									value={item.key}
									data-testid="search-result"
									onSelect={() => void navigate(item.href)}
									className="flex flex-col items-start gap-2 border-b px-4 py-3"
								>
									<span className="text-xs text-muted-foreground">
										{item.sourceLabel}
									</span>
									<span className="font-medium">{item.title}</span>
									{item.snippet && (
										<span className="text-sm text-muted-foreground">
											{item.snippet}
										</span>
									)}
								</CommandItem>
							))}
					</CommandList>
				</Command>
				{!result.error && state.q.trim() && result.data && (
					<>
						{result.data.truncated && (
							<p className="text-xs text-muted-foreground">
								Showing a limited result window. Refine your query to find more
								content.
							</p>
						)}
						<SearchPagination
							page={state.page}
							hasMore={result.data.hasMore}
							loading={loading}
							onPageChange={(page) => setState({ page })}
						/>
					</>
				)}
			</DialogContent>
		</Dialog>
	);
}

/** Trigger for the shared dialog, including the optional Cmd/Ctrl+K shortcut. */
export interface SearchInputProps extends SearchPresentationProps {
	triggerClassName?: string;
	buttonText?: string;
	/** Disable when a page contains several independently scoped triggers. */
	keyboardShortcut?: boolean;
}

export function SearchInput({
	triggerClassName,
	buttonText = "Search",
	keyboardShortcut = true,
	...props
}: SearchInputProps) {
	const [open, setOpen] = useState(false);
	const trigger = useRef<HTMLButtonElement>(null);
	const onOpenChange = (nextOpen: boolean) => {
		setOpen(nextOpen);
		if (!nextOpen) requestAnimationFrame(() => trigger.current?.focus());
	};
	useEffect(() => {
		if (!keyboardShortcut) return;
		const onKeyDown = (event: KeyboardEvent) => {
			if (event.key.toLowerCase() === "k" && (event.metaKey || event.ctrlKey)) {
				event.preventDefault();
				setOpen(!open);
				if (open) requestAnimationFrame(() => trigger.current?.focus());
			}
		};
		document.addEventListener("keydown", onKeyDown);
		return () => document.removeEventListener("keydown", onKeyDown);
	}, [keyboardShortcut, open]);
	return (
		<>
			<Button
				ref={trigger}
				type="button"
				variant="outline"
				className={triggerClassName}
				data-testid="search-button"
				aria-haspopup="dialog"
				aria-expanded={open}
				onClick={() => setOpen(true)}
			>
				{buttonText}
				{keyboardShortcut && (
					<kbd className="ml-6 text-xs text-muted-foreground">⌘K</kbd>
				)}
			</Button>
			<SearchDialog {...props} open={open} onOpenChange={onOpenChange} />
		</>
	);
}

"use client";

import { useStack } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import type { SearchResponse } from "../../types";

export function SearchStatus({
	query,
	data,
	loading,
	error,
	emptyMessage = "No results found.",
	onRetry,
}: {
	query: string;
	data?: SearchResponse;
	loading: boolean;
	error: Error | null | undefined;
	emptyMessage?: string;
	onRetry: () => void;
}) {
	if (error) {
		return (
			<div className="space-y-3 p-4" role="alert">
				<p>Search could not be completed. Check your access or try again.</p>
				<Button type="button" variant="outline" onClick={onRetry}>
					Retry search
				</Button>
			</div>
		);
	}
	if (loading)
		return (
			<p className="p-4 text-sm" role="status">
				Searching…
			</p>
		);
	if (!query.trim()) {
		return (
			<p className="p-4 text-sm text-muted-foreground">Enter a search term.</p>
		);
	}
	if (data?.items.length === 0) {
		return (
			<p className="p-4 text-sm text-muted-foreground" role="status">
				{emptyMessage}
			</p>
		);
	}
	return null;
}

export function SearchResults({ data }: { data: SearchResponse }) {
	const { router } = useStack();
	const Link = router?.Link ?? "a";
	return (
		<ul
			className="divide-y"
			aria-label="Search results"
			data-testid="search-results"
		>
			{data.items.map((item) => (
				<li key={item.key}>
					<Link
						href={item.href}
						className="block space-y-2 rounded-sm p-4 hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring"
						data-testid="search-result"
					>
						<span className="block text-xs text-muted-foreground">
							{item.sourceLabel}
						</span>
						<span className="block font-medium">{item.title}</span>
						{item.snippet && (
							<span className="block text-sm text-muted-foreground">
								{item.snippet}
							</span>
						)}
					</Link>
				</li>
			))}
		</ul>
	);
}

export function SearchPagination({
	page,
	hasMore,
	loading,
	onPageChange,
}: {
	page: number;
	hasMore: boolean;
	loading: boolean;
	onPageChange: (page: number) => void;
}) {
	return (
		<nav
			aria-label="Search pagination"
			className="flex items-center justify-between gap-3 border-t p-4 text-sm"
		>
			<Button
				type="button"
				variant="outline"
				disabled={page <= 1 || loading}
				onClick={() => onPageChange(page - 1)}
			>
				Previous page
			</Button>
			<span>Page {page}</span>
			<Button
				type="button"
				variant="outline"
				disabled={!hasMore || loading}
				onClick={() => onPageChange(page + 1)}
			>
				Next page
			</Button>
		</nav>
	);
}

"use client";

import { useId } from "react";
import type { SearchResponse } from "../../types";

export function SourceFilter({
	sources,
	value,
	onChange,
}: {
	sources: SearchResponse["sources"];
	value: string;
	onChange: (source: string) => void;
}) {
	const id = useId();
	return (
		<div className="flex flex-wrap items-center gap-3">
			<label htmlFor={id} className="text-sm font-medium">
				Source
			</label>
			<select
				id={id}
				className="min-h-10 max-w-full rounded-md border border-input bg-background px-3 text-sm focus-visible:outline-2 focus-visible:outline-ring"
				value={value}
				onChange={(event) => onChange(event.target.value)}
			>
				<option value="">All sources</option>
				{sources.map((source) => (
					<option key={source.id} value={source.id}>
						{source.label}
					</option>
				))}
			</select>
		</div>
	);
}

/** Presentation choices for the shared Search UI. */
export interface SearchPluginOverrides {
	/** Label above the results route. */
	title?: string;
	/** Search field prompt. */
	placeholder?: string;
	/** Message shown when a completed query has no matches. */
	emptyMessage?: string;
}

import {
	parseListStateFromSearchParams,
	type ListStateSchema,
} from "@btst/stack/client";
import { SEARCH_PLUGIN_ID } from "./constants";

export const SEARCH_LIST_STATE_SCHEMA = {
	q: { type: "string", default: "", history: "replace" },
	sources: { type: "string", default: "" },
	page: { type: "number", default: 1 },
} as const satisfies ListStateSchema;

export function parseSearchState(searchParams: URLSearchParams | string = "") {
	return parseListStateFromSearchParams(
		SEARCH_PLUGIN_ID,
		SEARCH_LIST_STATE_SCHEMA,
		searchParams,
	);
}

export type SearchListState = ReturnType<typeof parseSearchState>;
